// Original exercises. Each tuple is a complete question, with its own answer and correction.
// A shared bank is used only when the same prerequisite is taught in two chapters.
const N = (prompt, correct, unit, explanation, hint = 'Identifiez les données utiles, convertissez les unités puis appliquez la relation du chapitre.', tolerance = Math.max(Math.abs(correct) * .001, 1e-30)) => ({kind:'number', prompt, correct, unit, explanation, hint, tolerance});
const C = (prompt, correct, wrong1, wrong2, explanation, hint = 'Vérifiez les conditions du modèle et la signification des grandeurs.') => ({kind:'choice', prompt, options:[correct,wrong1,wrong2], correct:0, explanation, hint});
const banks = {};
const add = (id, ...questions) => { banks[id] = questions; };
const share = (target, source) => { banks[target] = banks[source].map(q => ({...q, ...(q.options ? {options:[...q.options]} : {})})); };

